-- Background automation execution that survives the browser being closed.
--
-- Supabase-native path (no Trigger.dev dependency): pg_cron fires every minute
-- and pg_net POSTs to the automation-tick Edge Function, which decides due
-- slots, reserves them idempotently, and invokes agent-runtime over HTTP.
--
-- The shared tick secret is generated by the database itself, stored in a
-- locked-down private schema, and never appears in cron.job.command.

create schema if not exists noska_private;

create table if not exists noska_private.tick_secrets (
  name text primary key,
  secret text not null,
  created_at timestamptz not null default now()
);

insert into noska_private.tick_secrets (name, secret)
values ('automation-tick', encode(extensions.gen_random_bytes(32), 'hex'))
on conflict (name) do nothing;

revoke all on schema noska_private from public;
revoke all on table noska_private.tick_secrets from anon, authenticated;
grant usage on schema noska_private to service_role;
grant select on noska_private.tick_secrets to service_role;

create or replace function public.automation_tick_secret()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select secret from noska_private.tick_secrets where name = 'automation-tick';
$$;

revoke all on function public.automation_tick_secret() from public, anon, authenticated;
grant execute on function public.automation_tick_secret() to service_role;

do $outer$
declare
  existing_job bigint;
begin
  for existing_job in select jobid from cron.job where jobname = 'noska-automation-tick' loop
    perform cron.unschedule(existing_job);
  end loop;

  perform cron.schedule(
    'noska-automation-tick',
    '* * * * *',
    $cron$
      select net.http_post(
        url := 'https://yxgtmzksnyarlivgxujf.supabase.co/functions/v1/automation-tick',
        headers := jsonb_build_object(
          'content-type', 'application/json',
          'x-tick-secret', public.automation_tick_secret()
        ),
        body := jsonb_build_object('source', 'pg_cron')
      );
    $cron$
  );
end;
$outer$;
